import React from "react";
import "./Questionnaire.css";
import Navbar from "./Navbar";

const rangeOptions = [
  "Below ₹10,000",
  "₹10,000 – ₹20,000",
  "₹20,000 – ₹30,000",
  "₹30,000 – ₹50,000",
  "₹50,000 – ₹75,000",
  "₹75,000 – ₹1,00,000",
  "Above ₹1,00,000",
  "Custom"   // ✅ RESTORED
];

function Questionnaire({ data, setData, onNext, onBack }) {

  const handleChange = (e) => {
    setData({
      ...data,
      [e.target.name]: e.target.value
    });
  };

  // ✅ Handle final value (custom OR selected)
  const getFinalIncome = () => {
    return data.incomeRange === "Custom"
      ? data.customIncome || ""
      : data.incomeRange;
  };

  const handleContinue = () => {
    const finalIncome = getFinalIncome();

    if (!finalIncome || !data.spendingRange || !data.savingRange) {
      alert("Please fill all fields");
      return;
    }

    // ✅ Save final processed value also
    setData({
      ...data,
      incomeRange: finalIncome
    });

    onNext();
  };

  return (
    <>
     <Navbar 
  title="Questionnaire"
  onBack={onBack}
  onNext={handleContinue}
  nextLabel="Spending"
/>

      <div className="questionnaire-container">
        <div className="questionnaire-card">

          <h2 className="questionnaire-title">Questionnaire</h2>

          <div style={{ display: "flex", gap: "30px", flexWrap: "wrap" }}>

            {/* LEFT */}
            <div style={{ flex: "1", minWidth: "300px" }}>
              <div className="form-group">
                <label className="form-label">Income Range</label>

                <select
                  className="form-select"
                  name="incomeRange"
                  value={data.incomeRange}
                  onChange={handleChange}
                >
                  <option value="">Select</option>
                  {rangeOptions.map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                  ))}
                </select>

                {/* ✅ CUSTOM INPUT RESTORED */}
                {data.incomeRange === "Custom" && (
                  <input
                    type="number"
                    name="customIncome"
                    placeholder="Enter your monthly income"
                    className="form-input"
                    value={data.customIncome || ""}
                    onChange={handleChange}
                    style={{ marginTop: "10px" }}
                  />
                )}
              </div>
            </div>

            {/* RIGHT */}
            <div style={{ flex: "1", minWidth: "300px" }}>
              <div className="form-group">
                <label className="form-label">Spending Range</label>
                <select
                  className="form-select"
                  name="spendingRange"
                  value={data.spendingRange}
                  onChange={handleChange}
                >
                  <option value="">Select</option>
                  {rangeOptions.slice(0, -1).map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label className="form-label">Saving Range</label>
                <select
                  className="form-select"
                  name="savingRange"
                  value={data.savingRange}
                  onChange={handleChange}
                >
                  <option value="">Select</option>
                  {rangeOptions.slice(0, -1).map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                  ))}
                </select>
              </div>
            </div>

          </div>

          <button className="next-button" onClick={handleContinue}>
            Continue
          </button>

        </div>
      </div>
    </>
  );
}

export default Questionnaire;
